import{_ as l,o as t,c as e,a2 as _}from"./chunks/framework.BXA5Pi9t.js";const k=JSON.parse('{"title":"CDS G/H (Day 1) - Wiki IA","description":"","frontmatter":{"title":"CDS G/H (Day 1) - Wiki IA","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-24T00:00:00.000Z","tags":["Ceph社区","Wiki页面建设","资源整合","Ceph资源","Ceph开发"],"categories":["Ceph会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_Wiki_IA.md","filePath":"posts/2014/CDS_G_H_Day_1_-_Wiki_IA.md","lastUpdated":1780459816000}'),p={name:"posts/2014/CDS_G_H_Day_1_-_Wiki_IA.md"};function a(s,i,r,o,n,u){return t(),e("div",null,[...i[0]||(i[0]=[_("<p>本次线上会议主要讨论了Ceph社区资源的整合和Wiki页面的建设方案。以下是会议的关键细节、主要议题、决定的事项以及后续行动计划：</p><p><strong>关键细节</strong>：</p><ul><li>主持人介绍了Ceph社区资源整合的需求，包括演讲者信息、事件日历、社区贡献者工具、程序指南、硬件兼容性指南、社区周边产品、贡献原因、学术推广、编排和部署工具、提交者名单、路线图、Chum Bucket和Paper Cuts、高价值文档等。</li><li>主持人提出了Wiki页面建设的初步方案，并对页面结构进行了讨论。</li><li>与会者对Wiki页面建设方案进行了反馈，并提出了一些改进意见。</li><li>主持人表示将开始实施Wiki页面建设方案，并呼吁大家积极参与。</li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>Ceph社区资源整合</li><li>Wiki页面建设方案</li><li>页面结构优化</li><li>学术推广</li><li>编排和部署工具</li><li>提交者名单</li><li>路线图</li><li>Chum Bucket和Paper Cuts</li><li>高价值文档</li></ul><p><strong>决定的事项</strong>：</p><ul><li>开始实施Wiki页面建设方案</li><li>呼吁大家积极参与Wiki页面建设</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>主持人将负责Wiki页面建设的主要工作</li><li>与会者将根据自身兴趣和能力，参与Wiki页面建设的相关工作</li><li>定期召开会议，讨论Wiki页面建设进展情况</li><li>推动Ceph Brag的使用，并优化相关统计数据的展示方式</li><li>进一步整合学术推广活动，鼓励更多高校参与</li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph社区</li><li>Wiki页面</li><li>资源整合</li><li>页面结构</li><li>Chum Bucket</li><li>Paper Cuts</li><li>学术推广</li><li>编排和部署工具</li><li>提交者名单</li><li>路线图</li><li>Ceph Brag</li><li>统计数据</li></ul>",11)])])}const W=l(p,[["render",a]]);export{k as __pageData,W as default};
